content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1000px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  text-align: center;
  margin-bottom: 8px;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

@media (max-width: 768px) {
  .main-content {
    grid-template-columns: 1fr;
  }
}

.chart-section,
.list-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  padding: 20px;
  box-shadow: var(--shadow);
}

.stats-summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  font-size: 1.1rem;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 12px;
}

.expense-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 300px;
  overflow-y: auto;
}

.expense-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;
}

.expense-item:hover {
  background-color: #f1f5f9;
  border-color: var(--border-color);
}

.item-info {
  display: flex;
  align-items: center;
  gap: 10px;
}

.item-color {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
}

.item-name {
  font-weight: 500;
  color: var(--text-main);
}

.item-amount {
  font-weight: 600;
  color: var(--text-main);
}

.detail-card {
  background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);
  border-left: 4px solid var(--primary-color);
}

.detail-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 8px;
}

.detail-amount {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary-color);
  margin-bottom: 12px;
}

.detail-note {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.empty-selection {
  text-align: center;
  color: var(--text-muted);
  font-style: italic;
  padding: 16px 0;
}

export interface ExpenseItem {
  id: string;
  name: string;
  amount: number;
  color: string;
}

export interface AppState {
  items: ExpenseItem[];
  selectedId: string | null;
}

import { useState } from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { ExpenseItem, AppState } from './types';
import './index.css';

const initialItems: ExpenseItem[] = [
  { id: '1', name: '食費', amount: 45000, color: '#4f46e5' },
  { id: '2', name: '家賃', amount: 80000, color: '#06b6d4' },
  { id: '3', name: '光熱費', amount: 15000, color: '#10b981' },
  { id: '4', name: '通信費', amount: 8000, color: '#f59e0b' },
  { id: '5', name: '交通費', amount: 12000, color: '#ef4444' },
  { id: '6', name: '娯楽・交際費', amount: 20000, color: '#8b5cf6' },
];

export default function App() {
  const [state, setState] = useState<AppState>({
    items: initialItems,
    selectedId: null,
  });

  const totalAmount = state.items.reduce((sum, item) => sum + item.amount, 0);
  const selectedItem = state.items.find(item => item.id === state.selectedId);

  const handleSelect = (id: string) => {
    setState(prev => ({
      ...prev,
      selectedId: prev.selectedId === id ? null : id,
    }));
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">家計簿ダッシュボード</h1>
      </header>

      <main className="main-content">
        <section className="chart-section">
          <div className="card">
            <div className="stats-summary">
              <span>支出内訳グラフ</span>
              <span>合計: ¥{totalAmount.toLocaleString()}</span>
            </div>
            <div style={{ width: '100%', height: 260 }}>
              <ResponsiveContainer>
                <PieChart>
                  <Pie
                    data={state.items}
                    dataKey="amount"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={80}
                    innerRadius={40}
                    onClick={(data: any) => {
                      if (data && data.id) {
                        handleSelect(data.id);
                      }
                    }}
                    cursor="pointer"
                  >
                    {state.items.map((entry) => (
                      <Cell key={`cell-${entry.id}`} fill={entry.color} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(value: number) => [`¥${value.toLocaleString()}`, '金額']} />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        </section>

        <section className="list-section">
          <div className="card">
            <div className="stats-summary">
              <span>支出項目一覧</span>
              <span>全 {state.items.length} 項目</span>
            </div>
            <ul className="expense-list">
              {state.items.map((item) => (
                <li
                  key={item.id}
                  className="expense-item"
                  onClick={() => handleSelect(item.id)}
                  style={{
                    backgroundColor: state.selectedId === item.id ? '#f1f5f9' : 'transparent',
                    borderColor: state.selectedId === item.id ? 'var(--primary-color)' : 'transparent',
                  }}
                >
                  <div className="item-info">
                    <span className="item-color" style={{ backgroundColor: item.color }} />
                    <span className="item-name">{item.name}</span>
                  </div>
                  <span className="item-amount">¥{item.amount.toLocaleString()}</span>
                </li>
              ))}
            </ul>
          </div>

          <div className="card detail-card">
            <h2 className="detail-title">項目詳細</h2>
            {selectedItem ? (
              <div>
                <div className="detail-amount">¥{selectedItem.amount.toLocaleString()}</div>
                <div className="detail-note">
                  選択中の項目: <strong>{selectedItem.name}</strong><br />
                  全体に対する割合: {((selectedItem.amount / totalAmount) * 100).toFixed(1)}%
                </div>
              </div>
            ) : (
              <div className="empty-selection">
                上のグラフまたは一覧から項目を選択すると、詳細が表示されます。
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
}
